    private ToggleButton selectTool,drawTool;private Tool tool=Tool.SELECT;private Target target=Target.SCENE;private EntityDef selected;private TileLayer selectedLayer;private boolean loading,dragging;private double dragX,dragY;private int lastPaintX=Integer.MIN_VALUE,lastPaintY=Integer.MIN_VALUE;private List<EntityDef>entityClipboard=List.of();private TileLayer layerClipboard;private Level sceneClipboard;

