    private Node centerPane(){ToggleGroup group=new ToggleGroup();selectTool=toolButton("Selección",group,true,Tool.SELECT);drawTool=toolButton("Dibujar",group,false,Tool.DRAW);ToggleButton fill=toolButton("Rellenar",group,false,Tool.FILL),erase=toolButton("Borrar",group,false,Tool.ERASE),empty=toolButton("Objeto",group,false,Tool.EMPTY_ENTITY);brushPicker.setPrefWidth(205);brushPicker.setCellFactory(v->brushCell());brushPicker.setButtonCell(brushCell());brushPicker.setOnAction(e->{if(loading)return;target=Target.BRUSH;selected=null;selectedEntities.clear();selectedLayer=null;loadScriptTarget();rebuildInspector();redraw();});zoomScale.setPrefWidth(62);zoomScale.setButtonCell(scaleCell());zoomScale.setCellFactory(v->scaleCell());zoomScale.valueProperty().addListener((o,a,b)->resizeCanvas());gridInfo.getStyleClass().add("muted");Region spacer=new Region();HBox.setHgrow(spacer,Priority.ALWAYS);HBox tools=new HBox(5,selectTool,drawTool,fill,erase,empty,new Separator(),new Label("Pincel:"),brushPicker,spacer,new Label("Zoom"),zoomScale,gridInfo);tools.setAlignment(Pos.CENTER_LEFT);tools.setPadding(new Insets(6,8,6,8));tools.getStyleClass().add("context-toolbar");StackPane shell=new StackPane(canvas);shell.getStyleClass().add("canvas-shell");shell.setPadding(new Insets(28));ScrollPane scroll=new ScrollPane(shell);scroll.setPannable(true);scroll.getStyleClass().add("editor-scroll");VBox center=new VBox(tools,scroll);VBox.setVgrow(scroll,Priority.ALWAYS);installCanvasHandlers();return center;}
    private ListCell<PrefabDef>brushCell(){return new ListCell<>(){@Override protected void updateItem(PrefabDef p,boolean empty){super.updateItem(p,empty);if(empty||p==null){setText(null);return;}setText(p.name+"  ·  "+effectivePlacement(p));}};}
    private ListCell<Integer>scaleCell(){return new ListCell<>(){@Override protected void updateItem(Integer item,boolean empty){super.updateItem(item,empty);setText(empty||item==null?"":item+"×");}};}
    private ToggleButton toolButton(String text,ToggleGroup group,boolean active,Tool next){ToggleButton b=new ToggleButton(text);b.setToggleGroup(group);b.setSelected(active);b.setOnAction(e->{if(!b.isSelected()){b.setSelected(true);return;}tool=next;lastPaintX=lastPaintY=Integer.MIN_VALUE;if(next==Tool.DRAW||next==Tool.FILL){target=Target.BRUSH;selected=null;selectedEntities.clear();hierarchy.getSelectionModel().clearSelection();loadScriptTarget();rebuildInspector();}app.status(switch(next){case SELECT->"Seleccionar: clic y arrastre sobre entidades.";case DRAW->"Dibujar: el Pincel usa tilemap o Prefab automáticamente.";case FILL->"Rellenar: disponible para Pinceles que usan TILEMAP.";case ERASE->"Borrar: elimina celdas tilemap al arrastrar.";case EMPTY_ENTITY->"Objeto vacío: coloca una entidad sin Prefab.";});redraw();});return b;}

    private Node rightPane(){tabs.setTabClosingPolicy(TabPane.TabClosingPolicy.UNAVAILABLE);tabs.setPrefWidth(380);ScrollPane inspectorScroll=new ScrollPane(inspector);inspectorScroll.setFitToWidth(true);inspectorScroll.getStyleClass().add("editor-scroll");inspectorTab.setContent(inspectorScroll);scriptTab.setContent(scriptPane());tabs.getTabs().addAll(inspectorTab,scriptTab);return tabs;}
    private Node scriptPane(){script.setStyle("-fx-font-family:'Consolas','JetBrains Mono',monospace;-fx-font-size:13px;");script.setWrapText(false);script.textProperty().addListener((o,a,b)->{if(!loading){setTargetScript(b);app.changed();validate(false);}});Button validate=new Button("Validar script"),template=new Button("Insertar plantilla"),tutorial=new Button("Tutorial + API");validate.getStyleClass().add("primary-button");validate.setOnAction(e->validate(true));template.setOnAction(e->script.setText(template()));tutorial.setOnAction(e->ScriptTutorialDialog.show(app.owner(),this::insertTutorialExample));Label help=muted("El Script puede pertenecer a escena, capa, entidad o Prefab/Pincel. El tutorial contiene cada comando, firma, componente y ejemplos WASD/salto.");VBox box=new VBox(8,new HBox(8,validate,template,tutorial),scriptStatus,script,help);box.setPadding(new Insets(12));VBox.setVgrow(script,Priority.ALWAYS);return box;}
    private void insertTutorialExample(String example){if(example==null||example.isBlank())return;int caret=Math.max(0,Math.min(script.getCaretPosition(),script.getLength()));String before=script.getText(0,caret),after=script.getText(caret,script.getLength());String prefix=caret==0?"":before.endsWith("\n\n")?"":before.endsWith("\n")?"\n":"\n\n",suffix=after.isEmpty()?"":after.startsWith("\n\n")?"":after.startsWith("\n")?"\n":"\n\n";script.insertText(caret,prefix+example.strip()+suffix);tabs.getSelectionModel().select(scriptTab);script.requestFocus();}

    private void installCanvasHandlers(){canvas.setOnMousePressed(e->{canvas.requestFocus();Level l=level();if(l==null)return;double cell=cellSize(),wx=e.getX()/cell,wy=e.getY()/cell;int cx=cellX(e.getX()),cy=cellY(e.getY());if(e.getButton()==MouseButton.SECONDARY){if(tool==Tool.DRAW||tool==Tool.ERASE)eraseTile(cx,cy);return;}switch(tool){case SELECT->selectAt(wx,wy,e);case DRAW->paintBrush(cx,cy);case FILL->fillBrush(cx,cy);case ERASE->eraseTile(cx,cy);case EMPTY_ENTITY->{EntityDef created=createEmpty(wx,wy);selectCreated(created);tool=Tool.SELECT;selectTool.setSelected(true);}}});canvas.setOnMouseDragged(e->{double cell=cellSize(),wx=e.getX()/cell,wy=e.getY()/cell;if(tool==Tool.SELECT&&dragging&&selected!=null){double nx=snap(wx-dragX),ny=snap(wy-dragY),dx=nx-selected.x,dy=ny-selected.y;for(EntityDef ent:selectedEntities){ent.x=snap(ent.x+dx);ent.y=snap(ent.y+dy);}app.changed();redraw();}else if(tool==Tool.DRAW)paintBrush(cellX(e.getX()),cellY(e.getY()));else if(tool==Tool.ERASE)eraseTile(cellX(e.getX()),cellY(e.getY()));});canvas.setOnMouseReleased(e->{dragging=false;lastPaintX=lastPaintY=Integer.MIN_VALUE;if(selected!=null)rebuildInspector();});}
    private void selectAt(double wx,double wy,javafx.scene.input.MouseEvent e){EntityDef hit=hit(wx,wy);if(e.isControlDown()){if(hit!=null){if(selectedEntities.contains(hit))selectedEntities.remove(hit);else selectedEntities.add(hit);selected=selectedEntities.isEmpty()?null:selectedEntities.iterator().next();selectHierarchySet();}}else{selectedEntities.clear();if(hit!=null)selectedEntities.add(hit);selected=hit;selectHierarchySet();}if(selected!=null){target=Target.ENTITY;selectedLayer=null;tileLayers.getSelectionModel().clearSelection();dragging=true;dragX=wx-selected.x;dragY=wy-selected.y;if(e.getClickCount()>=2)tabs.getSelectionModel().select(scriptTab);}loadScriptTarget();rebuildInspector();redraw();}

    private void paintBrush(int x,int y){if(x==lastPaintX&&y==lastPaintY)return;lastPaintX=x;lastPaintY=y;Level l=level();PrefabDef p=brushPicker.getValue();if(l==null||p==null||x<0||y<0||x>=l.width||y>=l.height)return;if(useTilemap(p)){TileLayer layer=activeTileLayer();if(layer==null){app.status("Selecciona o crea una capa tilemap.");return;}if(layer.locked){app.status("La capa está bloqueada.");return;}ensureTile(p);layer.set(x,y,p.tileId);app.changed();redraw();}else{EntityDef e=instantiatePrefab(p,x,y);l.entities.add(e);app.changed();refreshHierarchy();redraw();}}
    private void fillBrush(int x,int y){Level l=level();PrefabDef p=brushPicker.getValue();TileLayer layer=activeTileLayer();if(l==null||p==null)return;if(!useTilemap(p)){app.status("Rellenar solo se aplica a Pinceles TILEMAP. Los Prefabs se colocan como entidades con Dibujar.");return;}if(layer==null||layer.locked)return;ensureTile(p);int old=layer.get(x,y),replacement=p.tileId;if(old==replacement)return;ArrayDeque<int[]>q=new ArrayDeque<>();boolean[]seen=new boolean[l.width*l.height];q.add(new int[]{x,y});while(!q.isEmpty()){int[]c=q.removeFirst();int cx=c[0],cy=c[1];if(cx<0||cy<0||cx>=l.width||cy>=l.height)continue;int idx=cy*l.width+cx;if(seen[idx]||layer.get(cx,cy)!=old)continue;seen[idx]=true;layer.set(cx,cy,replacement);q.add(new int[]{cx+1,cy});q.add(new int[]{cx-1,cy});q.add(new int[]{cx,cy+1});q.add(new int[]{cx,cy-1});}app.changed();redraw();}
    private void eraseTile(int x,int y){TileLayer layer=activeTileLayer();if(layer==null||layer.locked)return;layer.set(x,y,-1);app.changed();redraw();}
    private boolean useTilemap(PrefabDef p){if(p.placement==PlacementMode.TILEMAP)return true;if(p.placement==PlacementMode.ENTITY)return false;if(p.tileId<0)return false;if(p.template==null)return true;if(p.template.script!=null&&!p.template.script.replace("# Doble clic sobre una entidad para editar su script.","").trim().isBlank()&&!p.template.script.trim().equals("# Script de "+p.name))return false;for(ComponentDef c:p.template.components)if(!Set.of("SpriteRenderer","BoxCollider2D").contains(c.type))return false;return true;}
    private String effectivePlacement(PrefabDef p){return p.placement==PlacementMode.AUTO?(useTilemap(p)?"AUTO→TILEMAP":"AUTO→ENTIDAD"):p.placement.name();}
    private void ensureTile(PrefabDef p){if(p.tileId>=0&&app.project().getTiles().containsKey(p.tileId))return;int id=app.project().nextTileId();String asset=p.template==null?"":p.template.assetKey;app.project().getTiles().put(id,new TileDef(id,p.name,new java.awt.Color(80,88,104),true,asset));p.tileId=id;}
    private EntityDef instantiatePrefab(PrefabDef p,double x,double y){EntityDef template=resolvePrefabTemplate(p,new HashSet<>());String id=uniqueEntityId(p.key);EntityDef e=cloneWithId(template,id);e.name=p.name;e.x=snap(x);e.y=snap(y);e.prefabKey=p.key;return e;}
    private EntityDef resolvePrefabTemplate(PrefabDef p,Set<String>seen){if(p==null||!seen.add(p.key))return new EntityDef("prefab","Prefab",0,0);EntityDef base=p.parentPrefab.isBlank()?null:resolvePrefabTemplate(app.project().getPrefabs().get(p.parentPrefab),seen);if(base==null)base=p.template==null?new EntityDef(p.key,p.name,0,0):p.template.copy();else if(p.template!=null)overlay(base,p.template);for(var o:p.variantOverrides.entrySet())override(base,o.getKey(),o.getValue());return base;}
    private static void overlay(EntityDef base,EntityDef child){if(!child.assetKey.isBlank())base.assetKey=child.assetKey;base.width=child.width;base.height=child.height;base.renderLayer=child.renderLayer;base.physicsLayer=child.physicsLayer;if(child.script!=null&&!child.script.isBlank())base.script=child.script;for(ComponentDef c:child.components){base.components.removeIf(x->x.type.equals(c.type));base.components.add(c.copy());}base.variables.putAll(child.variables);}
    private static void override(EntityDef e,String path,String value){String[]p=path.split("\\.");if(p.length==2){ComponentDef c=e.component(p[0]);if(c!=null)c.properties.put(p[1],value);}else if(path.equals("sprite")||path.equals("asset"))e.assetKey=value;}
    private static EntityDef cloneWithId(EntityDef source,String id){EntityDef e=new EntityDef(id,source.name,source.x,source.y);e.width=source.width;e.height=source.height;e.enabled=source.enabled;e.layer=source.layer;e.group=source.group;e.renderLayer=source.renderLayer;e.physicsLayer=source.physicsLayer;e.assetKey=source.assetKey;e.script=source.script;e.prefabKey=source.prefabKey;source.components.forEach(c->e.components.add(c.copy()));e.variables.putAll(source.variables);e.prefabOverrides.putAll(source.prefabOverrides);return e;}

    private void refresh(){loading=true;scenePicker.setItems(FXCollections.observableArrayList(app.project().getLevels().values()));if(!scenePicker.getItems().isEmpty()){Level start=app.project().getLevels().get(app.project().getStartLevel());scenePicker.setValue(start==null?scenePicker.getItems().getFirst():start);}brushPicker.setItems(FXCollections.observableArrayList(app.project().getPrefabs().values()));if(!brushPicker.getItems().isEmpty())brushPicker.setValue(brushPicker.getItems().getFirst());selected=null;selectedEntities.clear();selectedLayer=null;target=Target.SCENE;refreshTileLayers(false);refreshHierarchy();resizeCanvas();loading=false;loadScriptTarget();rebuildInspector();}
    private void refreshTileLayers(boolean preserve){Level l=level();TileLayer previous=preserve?selectedLayer:null;List<TileLayer>ordered=l==null?List.of():l.tileLayers.stream().sorted(Comparator.comparingInt(a->a.order)).toList();loading=true;tileLayers.setItems(FXCollections.observableArrayList(ordered));if(previous!=null&&tileLayers.getItems().contains(previous))tileLayers.getSelectionModel().select(previous);else tileLayers.getSelectionModel().clearSelection();loading=false;}
    private void refreshHierarchy(){Level l=level();TreeItem<HierarchyNode>root=new TreeItem<>(new HierarchyNode("ROOT","",null));hierarchy.setRoot(root);if(l==null)return;LinkedHashMap<String,List<EntityDef>>groups=new LinkedHashMap<>();for(EntityDef e:l.entities)groups.computeIfAbsent(e.group==null||e.group.isBlank()?"(Sin grupo)":e.group,k->new ArrayList<>()).add(e);for(var entry:groups.entrySet()){String groupName=entry.getKey();TreeItem<HierarchyNode>groupItem=new TreeItem<>(new HierarchyNode(groupName,groupName,null));groupItem.setExpanded(expandedGroups.contains(groupName)||groups.size()==1);groupItem.expandedProperty().addListener((o,a,b)->{if(b)expandedGroups.add(groupName);else expandedGroups.remove(groupName);});for(EntityDef e:entry.getValue())groupItem.getChildren().add(new TreeItem<>(new HierarchyNode((e.prefabKey.isBlank()?"":"◆ ")+e.name,groupName,e)));root.getChildren().add(groupItem);}selectHierarchySet();}
    private void selectHierarchySet(){loading=true;hierarchy.getSelectionModel().clearSelection();TreeItem<HierarchyNode>root=hierarchy.getRoot();if(root!=null)for(TreeItem<HierarchyNode>group:root.getChildren())for(TreeItem<HierarchyNode>child:group.getChildren())if(selectedEntities.contains(child.getValue().entity())){group.setExpanded(true);hierarchy.getSelectionModel().select(child);}loading=false;}
    private Level level(){return scenePicker.getValue();}private TileLayer activeTileLayer(){if(selectedLayer!=null)return selectedLayer;TileLayer s=tileLayers.getSelectionModel().getSelectedItem();if(s!=null)return s;Level l=level();return l==null||l.tileLayers.isEmpty()?null:l.baseLayer();}
    private int cellX(double x){return(int)Math.floor(x/cellSize());}private int cellY(double y){return(int)Math.floor(y/cellSize());}private double cellSize(){return app.project().getTileSize()*Math.max(1,zoomScale.getValue()==null?1:zoomScale.getValue());}private double snap(double v){return Math.rint(v*4)/4.0;}
    private void resizeCanvas(){Level l=level();if(l==null)return;double cell=cellSize();canvas.setWidth(Math.rint(l.width*cell));canvas.setHeight(Math.rint(l.height*cell));gridInfo.setText("Celda "+app.project().getTileSize()+" px · vista "+(zoomScale.getValue()==null?1:zoomScale.getValue())+"×");redraw();}

    private void redraw(){Level l=level();if(l==null)return;double cell=cellSize();GraphicsContext g=canvas.getGraphicsContext2D();g.setImageSmoothing(false);drawBackground(g,l,cell);List<RenderPass>passes=new ArrayList<>();for(TileLayer layer:l.tileLayers)if(layer.visible)passes.add(new RenderPass(layer.order*1000,()->drawTileLayer(g,l,layer,cell)));for(EntityDef e:l.entities)if(e.enabled)passes.add(new RenderPass(entityZ(e),()->drawEntity(g,e,cell)));passes.stream().sorted(Comparator.comparingInt(RenderPass::z)).forEach(p->p.draw.run());g.setStroke(Color.rgb(255,255,255,.10));g.setLineWidth(1);for(int x=0;x<=l.width;x++)g.strokeLine(Math.rint(x*cell)+.5,0,Math.rint(x*cell)+.5,canvas.getHeight());for(int y=0;y<=l.height;y++)g.strokeLine(0,Math.rint(y*cell)+.5,canvas.getWidth(),Math.rint(y*cell)+.5);for(EntityDef e:selectedEntities)drawSelection(g,e,cell);}
    private void drawBackground(GraphicsContext g,Level l,double cell){g.setFill(fx(l.backgroundColor));g.fillRect(0,0,canvas.getWidth(),canvas.getHeight());if(l.backgroundAssetKey.isBlank()||app.image(l.backgroundAssetKey)==null||l.backgroundMode==BackgroundMode.COLOR)return;double w=canvas.getWidth(),h=canvas.getHeight();int aw=app.assetWidth(l.backgroundAssetKey),ah=app.assetHeight(l.backgroundAssetKey);if(aw<=0||ah<=0)return;switch(l.backgroundMode){case STRETCH->app.drawAsset(g,l.backgroundAssetKey,0,0,w,h);case COVER,CONTAIN->{double s=l.backgroundMode==BackgroundMode.COVER?Math.max(w/aw,h/ah):Math.min(w/aw,h/ah),dw=aw*s,dh=ah*s;app.drawAsset(g,l.backgroundAssetKey,(w-dw)/2,(h-dh)/2,dw,dh);}case TILE->{for(double y=0;y<h;y+=ah)for(double x=0;x<w;x+=aw)app.drawAsset(g,l.backgroundAssetKey,x,y,aw,ah);}default->{}}}
    private void drawTileLayer(GraphicsContext g,Level l,TileLayer layer,double cell){double alpha=g.getGlobalAlpha();g.setGlobalAlpha(layer.opacity);for(int y=0;y<l.height;y++)for(int x=0;x<l.width;x++){int id=layer.get(x,y);if(id<0)continue;TileDef t=app.project().getTiles().get(id);if(t==null)continue;String asset=t.animationClip==null||t.animationClip.isBlank()?AdvancedTileResolver.assetFor(app.project(),l,layer,x,y,t):t.assetKey;if(!t.animationClip.isBlank()){AnimationClip clip=app.project().getAnimationClips().get(t.animationClip);if(clip!=null&&!clip.frames.isEmpty())asset=clip.frames.getFirst().assetKey;}if(!asset.isBlank()&&app.image(asset)!=null)app.drawAsset(g,asset,x*cell,y*cell,cell,cell);else{g.setFill(fx(t.color));g.fillRect(x*cell,y*cell,cell,cell);}}g.setGlobalAlpha(alpha);}
    private int entityZ(EntityDef e){ComponentDef sg=e.component("SortingGroup");int order=sg==null?e.layer:(int)Math.round(sg.number("order",e.layer));boolean ys=sg!=null&&sg.bool("ySort",false);return app.project().renderOrder(e.renderLayer)*100000+50000+order*100+(ys?(int)Math.round(e.y*10):0);}
    private void drawEntity(GraphicsContext g,EntityDef e,double cell){String asset=e.assetKey;ComponentDef animator=e.component("Animator");if(animator!=null){String clipKey=animator.get("clip","");AnimatorController controller=app.project().getAnimatorControllers().get(animator.get("controller",""));if(controller!=null){String state=animator.get("state",controller.defaultState);AnimatorState st=controller.states.get(state);if(st!=null)clipKey=st.clipKey;}AnimationClip clip=app.project().getAnimationClips().get(clipKey);if(clip!=null&&!clip.frames.isEmpty())asset=clip.frames.getFirst().assetKey;}double x=e.x*cell,y=e.y*cell,w=Math.max(4,e.width*cell),h=Math.max(4,e.height*cell);if(!asset.isBlank()&&app.image(asset)!=null)app.drawAsset(g,asset,x,y,w,h);else{g.setFill(Color.web("#4da7dc"));g.fillRoundRect(x,y,w,h,5,5);g.setStroke(Color.WHITE);g.strokeRoundRect(x,y,w,h,5,5);}}
    private void drawSelection(GraphicsContext g,EntityDef e,double cell){g.setStroke(Color.web("#42c7ff"));g.setLineWidth(2);g.strokeRect(Math.rint(e.x*cell)-2,Math.rint(e.y*cell)-2,Math.rint(e.width*cell)+4,Math.rint(e.height*cell)+4);ComponentDef c=e.component("BoxCollider2D");if(c!=null){g.setStroke(Color.web("#ffbf55"));double ox=c.number("offsetX",0),oy=c.number("offsetY",0),w=c.number("width",e.width),h=c.number("height",e.height);g.strokeRect((e.x+ox)*cell,(e.y+oy)*cell,w*cell,h*cell);}ComponentDef patrol=e.component("Patrol");if(patrol!=null){g.setStroke(Color.web("#ff6aa8"));double dist=patrol.number("distance",4);if(patrol.get("axis","x").equalsIgnoreCase("y"))g.strokeLine((e.x+e.width/2)*cell,e.y*cell,(e.x+e.width/2)*cell,(e.y+dist)*cell);else g.strokeLine(e.x*cell,(e.y+e.height/2)*cell,(e.x+dist)*cell,(e.y+e.height/2)*cell);}}
    private static Color fx(java.awt.Color c){return Color.rgb(c.getRed(),c.getGreen(),c.getBlue(),c.getAlpha()/255.0);}
    private EntityDef hit(double wx,double wy){Level l=level();if(l==null)return null;return l.entities.stream().filter(e->e.enabled&&wx>=e.x&&wy>=e.y&&wx<=e.x+e.width&&wy<=e.y+e.height).max(Comparator.comparingInt(this::entityZ)).orElse(null);}

